// ============================================================================
// phone_soc_iommu_regs -- APB4 register file generated by socgen from
// register_blocks.iommu in socgen/specs/phone_soc.yaml. IOMMU control, page-table base, TLB maintenance and fault reporting
//  - zero wait states, 32-bit data, 12-bit byte address, PSTRB byte lanes
//  - PSLVERR on an unmapped or misaligned offset
//  - hw_* inputs: values of RO registers and set pulses of W1C bits (from the
//    block's logic; tie to 0 for a register-only model)
// ============================================================================
module phone_soc_iommu_regs (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  input  logic [31:0] hw_fault_status,
  input  logic [31:0] hw_fault_addr,
  input  logic [31:0] hw_fault_cnt,
  input  logic [31:0] hw_tlb_hits,
  input  logic [31:0] hw_tlb_misses,
  output logic [31:0] q_ctrl,
  output logic [31:0] q_pt_base,
  output logic [31:0] q_va_base,
  output logic [31:0] q_va_size,
  output logic [31:0] q_inv,
  output logic        we_inv
);
  wire        acc   = PSEL & PENABLE;
  wire        wr    = acc & PWRITE;
  wire [31:0] wmask = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic       hit;
  always_comb begin
    hit = 1'b0;
    case (PADDR)
      12'h000: hit = 1'b1;
      12'h004: hit = 1'b1;
      12'h008: hit = 1'b1;
      12'h00C: hit = 1'b1;
      12'h010: hit = 1'b1;
      12'h014: hit = 1'b1;
      12'h018: hit = 1'b1;
      12'h01C: hit = 1'b1;
      12'h020: hit = 1'b1;
      12'h024: hit = 1'b1;
      12'h028: hit = 1'b1;
      default: hit = 1'b0;
    endcase
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~hit;

  // 000 ID RO reset 0x494F0100: code 0x494F ('IO'), version 1.0
  // 004 CTRL RW reset 0x00000000
  logic [31:0] r_ctrl;
  always_ff @(posedge PCLK or negedge PRESETN)
    if (!PRESETN) r_ctrl <= 32'h00000000;
    else if (wr && PADDR == 12'h004)
      r_ctrl <= ((r_ctrl & ~wmask) | (PWDATA & wmask)) & 32'h00000003;
  assign q_ctrl = r_ctrl;
  // 008 PT_BASE RW reset 0x00000000
  logic [31:0] r_pt_base;
  always_ff @(posedge PCLK or negedge PRESETN)
    if (!PRESETN) r_pt_base <= 32'h00000000;
    else if (wr && PADDR == 12'h008)
      r_pt_base <= ((r_pt_base & ~wmask) | (PWDATA & wmask)) & 32'hFFFFF000;
  assign q_pt_base = r_pt_base;
  // 00C VA_BASE RW reset 0x00000000
  logic [31:0] r_va_base;
  always_ff @(posedge PCLK or negedge PRESETN)
    if (!PRESETN) r_va_base <= 32'h00000000;
    else if (wr && PADDR == 12'h00C)
      r_va_base <= ((r_va_base & ~wmask) | (PWDATA & wmask)) & 32'hFFFFF000;
  assign q_va_base = r_va_base;
  // 010 VA_SIZE RW reset 0x00000000
  logic [31:0] r_va_size;
  always_ff @(posedge PCLK or negedge PRESETN)
    if (!PRESETN) r_va_size <= 32'h00000000;
    else if (wr && PADDR == 12'h010)
      r_va_size <= ((r_va_size & ~wmask) | (PWDATA & wmask)) & 32'hFFFFF000;
  assign q_va_size = r_va_size;
  // 014 INV WO reset 0x00000000: write 1 to invalidate the TLB
  logic [31:0] r_inv;
  always_ff @(posedge PCLK or negedge PRESETN)
    if (!PRESETN) r_inv <= 32'h00000000;
    else if (wr && PADDR == 12'h014)
      r_inv <= ((r_inv & ~wmask) | (PWDATA & wmask)) & 32'hFFFFFFFF;
  assign q_inv = r_inv;
  assign we_inv = wr && PADDR == 12'h014;
  // 018 FAULT_STATUS W1C reset 0x00000000
  logic [31:0] r_fault_status;
  always_ff @(posedge PCLK or negedge PRESETN)
    if (!PRESETN) r_fault_status <= 32'h00000000;
    else r_fault_status <= ((r_fault_status & ~((wr && PADDR == 12'h018) ? (PWDATA & wmask) : 32'h0))
                         | hw_fault_status) & 32'h00000007;
  // 01C FAULT_ADDR RO reset 0x00000000
  // 020 FAULT_CNT RO reset 0x00000000
  // 024 TLB_HITS RO reset 0x00000000
  // 028 TLB_MISSES RO reset 0x00000000

  always_comb begin
    PRDATA = 32'h0;
    if (acc && !PWRITE)
      case (PADDR)
        12'h000: PRDATA = 32'h494F0100;
        12'h004: PRDATA = r_ctrl;
        12'h008: PRDATA = r_pt_base;
        12'h00C: PRDATA = r_va_base;
        12'h010: PRDATA = r_va_size;
        12'h014: PRDATA = 32'h0;
        12'h018: PRDATA = r_fault_status;
        12'h01C: PRDATA = hw_fault_addr & 32'hFFFFFFFF;
        12'h020: PRDATA = hw_fault_cnt & 32'hFFFFFFFF;
        12'h024: PRDATA = hw_tlb_hits & 32'hFFFFFFFF;
        12'h028: PRDATA = hw_tlb_misses & 32'hFFFFFFFF;
        default: PRDATA = 32'h0;
      endcase
  end
endmodule
